'use strict';
const menu=document.querySelector('#menu');const nav=document.querySelector('#navigation');
menu?.addEventListener('click',()=>{const expanded=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!expanded));nav.classList.toggle('open',!expanded)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu?.getAttribute('aria-expanded')==='true'){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.focus()}});
const form=document.querySelector('#brief');form?.addEventListener('submit',event=>{event.preventDefault();if(!form.reportValidity())return;const data=new FormData(form);const ar=document.documentElement.lang==='ar';const labels=ar?['الاسم','البريد','المنشأة','المسار','الهدف','التحدي']:['Name','Email','Organisation','Route','Objective','Challenge'];const keys=['name','email','company','route','objective','challenge'];const brief=(ar?'ملخص طلب — بزنس أوربت':'Business Orbit — Enquiry brief')+'\n\n'+keys.map((key,i)=>labels[i]+': '+String(data.get(key)||'').trim()).join('\n\n')+'\n\n'+(ar?'هذا الملخص لم يُرسل إلى الشركة.':'This brief has not been sent to the company.');const url=URL.createObjectURL(new Blob([brief],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='business-orbit-enquiry.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#form-status').textContent=ar?'تم تجهيز الملخص للتنزيل. لم يُرسل طلب تواصل.':'Your brief is ready to download. No enquiry was submitted.'});
